mapper.select:
SELECT sc.id, sc.so_id AS soId, sc.code, sc.approve_status AS approveStatus, sc.invalid_status AS invalidStatus, sc.approve_user_name AS approveUserName, sc.create_user_name AS createUserName, sc.create_time AS createTime, si.code AS soCode, si.customer_id AS customerId, si.order_type AS orderType, scd.id as detailId, scd.sku_id AS skuId, scd.sku_no AS skuNo, scd.qty, scd.old_qty AS oldQty, scd.amount, scd.currency_symbol AS currencySymbol, scd.old_currency_symbol AS oldCurrencySymbol, scd.old_amount AS oldAmount FROM so_change sc INNER JOIN so_info si ON si.id=sc.so_id AND si.is_deleted=FALSE INNER JOIN so_change_detail scd ON sc.id=scd.main_id AND scd.is_deleted=FALSE WHERE ${params.sqlMap.default} and sc.is_deleted=false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sc.create_time DESC

SELECT sc.id, sc.so_id AS soId, sc.code, sc.approve_status AS approveStatus, sc.invalid_status AS invalidStatus, sc.approve_user_name AS approveUserName, sc.create_user_name AS createUserName, sc.create_time AS createTime, si.code AS soCode, si.customer_id AS customerId, si.order_type AS orderType, scd.sku_id AS skuId, scd.sku_no AS skuNo, scd.qty, scd.old_qty AS oldQty, scd.amount, scd.currency_symbol AS currencySymbol, scd.old_currency_symbol AS oldCurrencySymbol, scd.old_amount AS oldAmount FROM so_change sc INNER JOIN so_info si ON si.id=sc.so_id AND si.is_deleted=FALSE INNER JOIN so_change_detail scd ON sc.id=scd.main_id AND scd.is_deleted=FALSE WHERE ${params.sqlMap.default} and sc.is_deleted=false
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
sc.create_time DESC
